/* Ids dont le lien billetterie est une contrepartie commerciale (affiliation,
   partenariat payant). Google demande que ces liens sortants portent
   rel="sponsored" : sans ça, c'est un lien payant non déclaré, donc une
   infraction aux règles sur les liens — précisément ce qu'un site dont toute la
   valeur est le SEO ne peut pas se permettre. */
const SPONSORED_TICKETS = new Set<number>([
  25, // Positiv Festival → Ticketmaster
]);

/* Réseaux dont le tag Impact (`components/ImpactAffiliate.tsx`) réécrit
   automatiquement les liens sortants en liens affiliés. Tenir la liste à jour ici
   plutôt qu'événement par événement : `transformLinks` s'applique au domaine, pas à
   un id, donc tout lien vers ces hôtes est rémunéré **qu'on l'ait déclaré ou non** —
   et un lien payant non déclaré est une infraction aux règles de Google sur les
   liens. La liste explicite ci-dessus reste utile pour les partenariats négociés
   ailleurs (un lien direct organisateur, par exemple). */
const AFFILIATE_HOSTS = ["ticketmaster.", "livenation.", "ticketweb.", "evyy.net"];

/** Ticketing link: explicit URL, else Resident Advisor for paid events, null when free. */
export const ticketUrl = (e: RaveEvent): string | null =>
  TICKETS[e.id] ?? (e.price === 0 ? null : "https://ra.co");

/** Vrai quand le lien billetterie de cet événement est rémunéré. */
export const isSponsoredTicket = (e: RaveEvent): boolean => {
  if (SPONSORED_TICKETS.has(e.id)) return true;
  const u = TICKETS[e.id];
  return !!u && AFFILIATE_HOSTS.some((h) => u.includes(h));
};

/** `rel` du lien billetterie : "sponsored" en plus quand le lien est rémunéré. */
export const ticketRel = (e: RaveEvent): string =>
  isSponsoredTicket(e) ? "sponsored noopener noreferrer" : "noopener noreferrer";

export const ALL_GENRES = Object.keys(GENRES);
export const genreSlug = (g: string): string =>
  g.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
export const genreFromSlug = (s: string): string | undefined =>
  ALL_GENRES.find((g) => genreSlug(g) === s);
export const eventsForGenre = (g: string): RaveEvent[] =>
  upcomingFirst(EVENTS.filter((e) => e.genres.includes(g)));

export const slugify = (s: string): string =>
  s.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

/* A recurring festival has one entry per edition. The bare slug (/festival/sonar)
   belongs to the edition worth landing on — the next one if there is one, otherwise
   the most recent — and the other editions are suffixed with their year. That keeps
   one strong URL per festival instead of splitting authority across editions. */
const canonicalEditionId = (title: string): number => {
  const editions = EVENTS.filter((x) => x.title === title).sort((a, b) => a.date.localeCompare(b.date));
  return (editions.find((x) => !isPast(x)) ?? editions[editions.length - 1]).id;
};
export const eventSlug = (e: RaveEvent): string => {
  const base = slugify(e.title);
  return canonicalEditionId(e.title) === e.id ? base : `${base}-${e.date.slice(0, 4)}`;
};
export const eventFromSlug = (s: string): RaveEvent | undefined => EVENTS.find((e) => eventSlug(e) === s);
export const FESTIVALS: RaveEvent[] = EVENTS.filter((e) => e.type === "Festival");
/** SEO-friendly canonical path for an event (festivals live under /festival). */
export const eventPath = (e: RaveEvent): string =>
  e.type === "Festival" ? `/festival/${eventSlug(e)}` : `/event/${eventSlug(e)}`;

export const COUNTRIES = [...new Set(EVENTS.map((e) => e.country))].sort();
export const TYPES: RaveEvent["type"][] = ["Festival", "Club", "Warehouse"];

